input.command:
cat > Cargo.toml <<'EOF'
[package]
name = "win-tool"
version = "0.1.0"
edition = "2024"
description = "Windows-only command-line tool"
publish = false

# Windows API bindings. `windows-sys` gives raw, zero-overhead FFI declarations
# generated from Microsoft's metadata. Enable additional `Win32_*` features as
# you need more of the API surface (see https://microsoft.github.io/windows-rs/features).
[target.'cfg(windows)'.dependencies]
windows-sys = { version = "0.61.2", features = [
    "Win32_Foundation",
    "Win32_System_Threading",
    "Win32_UI_WindowsAndMessaging",
] }

[profile.release]
lto = true
codegen-units = 1
strip = true
EOF
cat > src/main.rs <<'EOF'
#[cfg(not(windows))]
compile_error!("win-tool only supports Windows targets");

use windows_sys::Win32::System::Threading::GetCurrentProcessId;
use windows_sys::Win32::UI::WindowsAndMessaging::{MB_ICONINFORMATION, MB_OK, MessageBoxW};
use windows_sys::w;

fn main() {
    // SAFETY: GetCurrentProcessId has no preconditions.
    let pid = unsafe { GetCurrentProcessId() };
    println!("Running as process {pid}");

    // SAFETY: a null owner window is allowed, and `w!` produces
    // NUL-terminated UTF-16 string literals with 'static lifetime.
    unsafe {
        MessageBoxW(
            std::ptr::null_mut(),
            w!("Hello from the Windows API"),
            w!("win-tool"),
            MB_OK | MB_ICONINFORMATION,
        );
    }
}
EOF
